import json, itertools, sys
sys.path.insert(0,'/app')
from main import solve
from test_ref import ref

def check(req):
    g = solve(req)
    eb, ef = ref(req)
    if int(g['bits'],16) != int(eb,16) or set(g['flags']) != set(ef):
        print('MISMATCH', json.dumps(req), 'got', g, 'want', {'bits':eb,'flags':ef})
        return False
    return True

bad = 0
# exhaustive single-pair, all modes, tiny formats
for ebits, fbits in [(3,2),(3,3),(4,2),(4,3),(5,4)]:
    w = 1 + ebits + fbits
    pats = list(range(1 << w))
    for mode in ['RNE','RNA','RTZ','RUP','RDN']:
        for a in pats:
            for b in pats:
                if not check({'ebits':ebits,'fbits':fbits,'mode':mode,
                              'pairs':[[format(a,'x'),format(b,'x')]]}):
                    bad += 1
                    if bad > 5: sys.exit(1)
    print('single-pair exhaustive ok', ebits, fbits)

# exhaustive two-pair for smallest format, all modes
for ebits, fbits in [(3,2)]:
    w = 1 + ebits + fbits
    pats = list(range(1 << w))
    pairs_all = [[format(a,'x'),format(b,'x')] for a in pats for b in pats]
    for mode in ['RNE','RNA','RTZ','RUP','RDN']:
        n = len(pairs_all)
        for i in range(n):
            for j in range(n):
                if not check({'ebits':ebits,'fbits':fbits,'mode':mode,
                              'pairs':[pairs_all[i],pairs_all[j]]}):
                    bad += 1
                    if bad > 5: sys.exit(1)
    print('two-pair exhaustive ok', ebits, fbits)
print('ALL OK' if bad == 0 else f'BAD {bad}')
